-- =====================================================================
-- TÉCNICA · FASE 1 · REPORTES DEL PTAP · 80 — VERIFICACIÓN DE SOLO LECTURA (una sola consulta; apta para el editor SQL web). Todas las filas deben decir OK.
-- =====================================================================
select k, v from (
  select 1 as o, '01 las 4 RPC: security definer, search_path fijo, solo service_role' as k,
         case when (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace
                     and p.proname = any (array['geoportal_tec_reporte_iniciar', 'geoportal_tec_reporte_pagina', 'geoportal_tec_reporte_cerrar', 'geoportal_tec_reporte_remision_foto'])
                     and p.prosecdef and p.proconfig is not null
                     and has_function_privilege('service_role', p.oid, 'execute') and not has_function_privilege('anon', p.oid, 'execute') and not has_function_privilege('authenticated', p.oid, 'execute')
                     and not exists (select 1 from aclexplode(p.proacl) x where x.grantee = 0)) = 4 then 'OK' else 'MAL' end as v
  union all select 2, '02 las funciones internas nuevas: nadie más que su dueño',
         case when not exists (select 1 from pg_proc p where p.pronamespace = 'tecnica'::regnamespace
                                and p.proname = any (array['f_rep_catalogo', 'f_rep_max_filas', 'f_rep_max_pagina', 'f_rep_ts', 'f_rep_col', 'f_rep_filtros', 'f_rep_cols_variables', 'f_rep_columnas', 'f_rep_valores', 'f_rep_envios_llaves', 'f_rep_envios_pagina', 'f_rep_envios',
                                                           'f_rep_quimicos', 'f_rep_kardex', 'f_rep_eventos_planta', 'f_rep_fuera_referencia', 'f_rep_filas', 'f_rep_leame'])
                                and exists (select 1 from aclexplode(p.proacl) x where x.grantee <> p.proowner)) then 'OK' else 'MAL' end
  union all select 3, '03 huellas md5 de las 22 nuevas',
         case when (select count(*) from (values ('geoportal_tec_reporte_cerrar(text,bigint,integer,text,text)', '2f76c0632a3bd6c7fc8ba054ef2ce3d0'), ('geoportal_tec_reporte_iniciar(text,text,jsonb,text,boolean,text)', '4c5c6acb1b81b545cbbc1865f45ac860'), ('geoportal_tec_reporte_pagina(text,bigint,text,integer)', '818a99308a99c880739ba08299cb0bce'), ('geoportal_tec_reporte_remision_foto(text,bigint,text)', 'd0ed2351fb3dfd2ab289e0688479e921'), ('tecnica.f_rep_catalogo()', '497bb7bd8d8867cd35dc362ef8ae4f94'), ('tecnica.f_rep_col(text,text,text,text,integer)', '03302ef51c4248764d7ba5b483b2d459'), ('tecnica.f_rep_cols_variables(text,date,date)', 'd46ff6aeacd556fb5fa5bf0c24eec8f7'), ('tecnica.f_rep_columnas(text,jsonb)', 'd178a29b3e4408b96b07bbaeae20f476'), ('tecnica.f_rep_envios(text,jsonb,boolean,timestamp with time zone,text,integer,jsonb,boolean)', '5adfbcb96a9ae77e2e2e61456a9e72ec'), ('tecnica.f_rep_envios_llaves(text,jsonb,boolean,timestamp with time zone,text,integer)', '9f8573b0fb8aeb4a99be41b1fe3f5cb0'), ('tecnica.f_rep_envios_pagina(text,jsonb,boolean,timestamp with time zone,text,integer,jsonb,date)', '27b983d1f6c6408322d5e761cecd671b'), ('tecnica.f_rep_eventos_planta(jsonb,boolean,timestamp with time zone,text,integer)', '5b97ed0684b94b94c14ec420aa1c212a'), ('tecnica.f_rep_filas(text,jsonb,boolean,timestamp with time zone,text,integer,jsonb,boolean)', '3322cf0a784a1822d1b48b34eb96d642'), ('tecnica.f_rep_filtros(text,jsonb)', 'a95c2f1e25415fbfd6b660b766da220c'), ('tecnica.f_rep_fuera_referencia(jsonb,boolean,timestamp with time zone,text,integer)', '7824ffb564ac569503870bba371a6bc0'), ('tecnica.f_rep_kardex(jsonb,timestamp with time zone,text,integer)', 'd9ef46b5af9ee5ac7ccfe308144f0d22'), ('tecnica.f_rep_leame(text,jsonb,boolean,text,timestamp with time zone)', '5f894b795ad896a7cc965b3ec5d37745'), ('tecnica.f_rep_max_filas()', '570dfa334c7e4cb8808dfebbb765bd14'), ('tecnica.f_rep_max_pagina()', '2c2200c266a01dd2ee191c24af93df53'), ('tecnica.f_rep_quimicos(text,jsonb,timestamp with time zone,text,integer)', 'd17b765a1230efba574b890d5dbfd6a8'), ('tecnica.f_rep_ts(timestamp with time zone)', '02a1cb1f4f2ef2d501b132eadaffeb0e'), ('tecnica.f_rep_valores(text[],jsonb,timestamp with time zone,date,bigint,date,boolean)', 'fb4317249f97dc75871c5c6be4019164')) c(f, m) where md5(pg_get_functiondef(to_regprocedure(c.f))) = c.m) = 22 then 'OK' else 'MAL' end
  union all select 4, '04 pg-safeupdate: ninguna función con DELETE o UPDATE sin WHERE',
         coalesce((select 'MAL: ' || string_agg(distinct funcion, ', ') from redes.f_funciones_sin_where()), 'OK')
  union all select 5, '05 la huella de redes no cambió con este paquete',
         case when (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) from pg_proc p
                     where p.pronamespace = 'redes'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%')) in ('b474fbbe3e0f7a3a7e6dbc04c53e02e7', '3f3c89e603629d92e1cc5065de33d0c1') then 'OK' else 'MAL' end
  union all select 6, '06 las 2 tablas nuevas: RLS, solo inserción y sin permisos para la API',
         case when (select count(*) from pg_class c where c.oid in ('tecnica.reporte_descargas'::regclass, 'tecnica.reporte_descarga_cierres'::regclass) and c.relrowsecurity
                     and not has_table_privilege('anon', c.oid, 'select') and not has_table_privilege('authenticated', c.oid, 'select') and not has_table_privilege('service_role', c.oid, 'select')
                     and (select count(*) from pg_trigger t where t.tgrelid = c.oid and t.tgname in ('t_solo_agregar', 't_solo_agregar_trunc')) = 2) = 2 then 'OK' else 'MAL' end
  union all select 7, 'INFO descargas iniciadas · cerradas', (select count(*) from tecnica.reporte_descargas) || ' · ' || (select count(*) from tecnica.reporte_descarga_cierres)
) t order by o;
